const node = new Proxy({ x: 0, world: null }, {
  set(target, prop, value, receiver) {
    if (prop === "x") target.world = null;      // any write invalidates
    return Reflect.set(target, prop, value, receiver);
  },
});

function world(n) { return (n.world ??= computeWorld(n.x)); }

import { reactive, computed } from "vue";

const node = reactive({ x: 0 });
const world = computed(() => computeWorld(node.x));   // cached until node.x changes

node.x += 1;                                          // dependency change -> dirty
console.log(world.value);                             // recomputed exactly once
